const MAX_MESSAGE_BYTES = 1024 * 1024;
const ALLOWED_ORIGINS = new Set(["https://app.example.com"]);

export function authorizeWebSocketUpgrade(
  origin: string,
  authenticated: boolean,
  messageBytes: number,
): 101 | 401 | 403 | 413 {
  if (!authenticated) return 401;
  if (!ALLOWED_ORIGINS.has(origin)) return 403;
  if (messageBytes > MAX_MESSAGE_BYTES) return 413;
  return 101;
}

