const REQUEST_ID = /^[a-z0-9-]{1,64}$/u;

export function classifyRequestInsight(
  requestIdHeader: string | undefined,
  serverOwnedActionEvidence: boolean,
) {
  const requestId = requestIdHeader && REQUEST_ID.test(requestIdHeader)
    ? requestIdHeader
    : undefined;

  return {
    requestId,
    serverAction: serverOwnedActionEvidence || undefined,
  };
}

