interface Core {
  getIDToken(audience: string): Promise<string>;
  setSecret(value: string): void;
}

const QUEUE = "https://next-maintainer-agent.vercel.tools";

export async function claimVerifiedClose(core: Core): Promise<Response> {
  const token = await core.getIDToken("next-maintainer-auto-close");
  core.setSecret(token);

  return fetch(`${QUEUE}/claim`, {
    method: "POST",
    headers: {
      authorization: `Bearer ${token}`,
      "x-vercel-trusted-oidc-idp-token": token,
    },
    redirect: "error",
    signal: AbortSignal.timeout(15_000),
  });
}

