export function restoreForwardedActionHost(input: {
  readonly marker: string | undefined;
  readonly isFetchAction: boolean;
  readonly host: string | undefined;
  readonly internalHost: string;
  readonly forwardedHost: string | undefined;
}): string | undefined {
  if (input.marker !== "1") return input.host;
  if (!input.isFetchAction) return input.host;
  if (!input.forwardedHost) return input.host;
  if (input.host !== input.internalHost) return input.host;
  return input.forwardedHost.split(",")[0]?.trim();
}

